fn icon_stroke_width(icon: Icon) -> f32 {
    match icon {
        Icon::FileTransfer => 1.5,
        Icon::LocalTerminal => 1.25,
        Icon::MarkdownDocument => 1.5,
        Icon::RemoteGlobe => 1.0,
        Icon::RunningSessions => 1.5,
        Icon::Serial => 1.25,
        Icon::SshRemote => 1.0,
        _ => 1.75,
    }
}
